function Title({ onCommit }) {
  const [text, setText] = useState("");
  let timer; // NOT a ref

  const schedule = (value) => {
    clearTimeout(timer);
    timer = setTimeout(() => onCommit(value), 1000);
  };

  return <input value={text} onChange={(e) => { setText(e.target.value); schedule(e.target.value); }} />;
}

